INSERT OR IGNORE INTO journeys (id,slug,title,kicker,summary,category,tags,clinical_note,status) VALUES ('hardship','hardship','When life feels overwhelming','PATIENT HOPE · REVELATION · PROPHETIC EXAMPLE','Quranic encouragement, verified incidents from the life of Rasulullah ﷺ, authentic supplication, and practical next steps for difficult days.','Life Guidance','hardship,patience,difficulty,trial,stress,life','Spiritual guidance does not replace psychological or medical care when needed.','published');
INSERT OR IGNORE INTO journeys (id,slug,title,kicker,summary,category,tags,clinical_note,status) VALUES ('anxiety','anxiety','When worry weighs on the heart','REMEMBRANCE · SUPPORT · WELLBEING','Explore Quranic guidance on remembrance, the Prophetic supplication for worry, and safe support for anxiety.','Wellbeing','anxiety,stress,worry,sadness,depression,mental health','If anxiety or low mood is persistent, disabling or involves risk of harm, seek professional medical or mental-health support. Spiritual practices can accompany treatment.','published');
INSERT OR IGNORE INTO journeys (id,slug,title,kicker,summary,category,tags,clinical_note,status) VALUES ('grief','grief','When you are grieving','MERCY · LOSS · PATIENCE','Quranic recognition of life’s trials and the tender example of the Prophet ﷺ when mourning his son.','Life Guidance','grief,loss,bereavement,sadness,death','Grief varies by person. Where functioning is significantly affected or safety is at risk, professional support matters.','published');
INSERT OR IGNORE INTO journeys (id,slug,title,kicker,summary,category,tags,clinical_note,status) VALUES ('debt','debt','When debt and livelihood feel heavy','FAIRNESS · RESPONSIBILITY · HOPE','A source-grounded approach to debt, hardship, fairness and constructive financial steps.','Worldly Affairs','debt,finance,livelihood,money,financial hardship,loan','This is ethical and spiritual guidance, not personalized legal or regulated financial advice.','published');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('hardship-q-94-5','hardship','tanzil','quran','Surah Ash-Sharh','94:5','فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا','Fa-inna maʿa l-ʿusri yusrā','Indeed, ease accompanies hardship.','The wording gives a basis for hope amid difficulty. It does not promise that every problem disappears immediately or without effort.','https://quran.com/94/5','','Quran','English meaning is a provisional explanatory rendering; Arabic requires canonical text QA before public release.','editorial_pending','published','1');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('hardship-q-94-6','hardship','tanzil','quran','Surah Ash-Sharh','94:6','إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا','Inna maʿa l-ʿusri yusrā','Indeed, alongside hardship there is ease.','The verse repeats the preceding reassurance. Read together with 94:5–8, it joins hope with devotion and continued striving.','https://quran.com/94/6','','Quran','English meaning is a provisional explanatory rendering; Arabic requires canonical text QA before public release.','editorial_pending','published','2');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('hardship-q-2-153','hardship','tanzil','quran','Surah Al-Baqarah','2:153','يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ','','Believers are instructed to seek help through patience and prayer; Allah is with those who are patient.','This is an explicit instruction to seek strength through patience and salah. It is not a prohibition on seeking assistance from people or professionals.','https://quran.com/2/153','','Quran','English meaning is a provisional explanatory rendering; Arabic requires canonical text QA before public release.','editorial_pending','published','3');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('anxiety-q-13-28','anxiety','tanzil','quran','Surah Ar-Raʿd','13:28','ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ','','Those who believe find reassurance of the heart in Allah’s remembrance; hearts find reassurance in His remembrance.','A spiritual teaching about remembrance and the heart. It should not be interpreted as a clinical promise that religious practice alone treats an anxiety disorder or depression.','https://quran.com/13/28','','Quran','English meaning is a provisional explanatory rendering; Arabic requires canonical text QA before public release.','editorial_pending','published','1');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('grief-q-2-155','grief','tanzil','quran','Surah Al-Baqarah','2:155','وَلَنَبْلُوَنَّكُم بِشَىْءٍۢ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍۢ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ ۗ وَبَشِّرِ ٱلصَّـٰبِرِينَ','','Allah tells believers they will experience tests involving fear, hunger, loss of wealth, life and crops, while giving glad tidings to the patient.','This passage names several kinds of real hardship without treating them as signs that one has no faith. The adjoining verses 2:156–157 describe responding to calamity.','https://quran.com/2/155','','Quran','English meaning is a provisional explanatory rendering; Arabic requires canonical text QA before public release.','editorial_pending','published','1');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('debt-q-2-153','debt','tanzil','quran','Surah Al-Baqarah','2:153','يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ','','Believers are instructed to seek help through patience and prayer; Allah is with those who are patient.','This is an explicit instruction to seek strength through patience and salah. It is not a prohibition on seeking assistance from people or professionals.','https://quran.com/2/153','','Quran','English meaning is a provisional explanatory rendering; Arabic requires canonical text QA before public release.','editorial_pending','published','1');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('hardship-seerah-3231','hardship','bukhari','seerah','Rejection and mercy after a painful day','Sahih al-Bukhari 3231','','','Aisha (RA) asked the Prophet ﷺ about the hardest day he faced. He described rejection during his call and, when an angel offered punishment of the people, he expressed hope that future generations would worship Allah alone.','A verified example of hope and mercy in the face of rejection; the historical episode should not be reduced to a promise of immediate relief.','https://sunnah.com/bukhari:3231','','Sahih al-Bukhari','Original editorial summary, not a verbatim Hadith translation.','editorial_pending','published','4');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('hardship-dua-6369','hardship','bukhari','dua','Prophetic supplication for worry and sorrow','Sahih al-Bukhari 6369','اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ','Allāhumma innī aʿūdhu bika mina l-hammi wa-l-ḥazan, wa-l-ʿajzi wa-l-kasal, wa-l-bukhli wa-l-jubn, wa-ḍalaʿi d-dayn, wa-ghalabati r-rijāl.','A supplication seeking Allah’s protection from worry, sorrow, helplessness, laziness, miserliness, cowardice, overwhelming debt, and being overpowered by people.','Read the complete narration and verify the exact Arabic text before relying on the transliteration for memorisation.','https://sunnah.com/bukhari:6369','','Sahih al-Bukhari','Arabic and romanization are educational draft, pronunciation should be learned from a qualified reciter.','editorial_pending','published','5');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('anxiety-dua-6369','anxiety','bukhari','dua','A supplication concerning anxiety and grief','Sahih al-Bukhari 6369','اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ','Allāhumma innī aʿūdhu bika mina l-hammi wa-l-ḥazan...','The Prophet ﷺ sought refuge with Allah from worry and grief, alongside several other difficulties.','This is spiritual support; it is not a replacement for professional treatment of clinical depression or anxiety disorders.','https://sunnah.com/bukhari:6369','','Sahih al-Bukhari','Full transliteration should be reviewed before publication.','editorial_pending','published','2');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('anxiety-medical','anxiety','who','clinical','When medical support is appropriate','WHO — Depression: overview','','','Depression and anxiety-related conditions can need professional assessment and treatment.','If symptoms persist, impair daily functioning, or safety is at risk, seek qualified support. Urgent risk needs emergency care.','https://www.who.int/news-room/fact-sheets/detail/depression','','Clinical source','General educational note; not a diagnosis.','editorial_pending','published','3');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('grief-seerah-1303','grief','bukhari','seerah','The Prophet ﷺ openly grieved for Ibrahim','Sahih al-Bukhari 1303','','','When his young son Ibrahim died, the Prophet ﷺ wept and expressed grief while remaining mindful of what he said.','His example shows that tears and sorrow are not inherently a failure of faith.','https://sunnah.com/bukhari:1303','','Sahih al-Bukhari','Original summary; full narrative must be shown only from appropriately licensed source.','editorial_pending','published','2');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('debt-sunnah-1563','debt','muslim','sunnah','Giving relief to someone facing debt hardship','Sahih Muslim 1563a','','','A related authenticated report encourages granting relief to someone who is unable to repay a debt on time.','This narration particularly concerns the creditor’s responsibility; it does not cancel the borrower’s obligation to act responsibly.','https://sunnah.com/muslim:1563a','','Sahih Muslim','Original summary; check exact scholarly interpretation.','editorial_pending','published','2');
INSERT OR IGNORE INTO evidence (id,journey_id,source_id,evidence_type,title,reference,arabic,transliteration,meaning,explanation,source_url,audio_url,source_grade,review_note,review_status,publish_status,sort_order) VALUES ('debt-dua-6369','debt','bukhari','dua','Seeking protection from burdensome debt','Sahih al-Bukhari 6369','اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ','','The supplication includes seeking Allah’s protection from the burden of debt.','Pair prayer with truthful communication, records, and suitable lawful financial assistance.','https://sunnah.com/bukhari:6369','','Sahih al-Bukhari','Arabic text pending review.','editorial_pending','published','3');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('hardship-s1','hardship','Name the difficulty you are facing without blaming yourself.','reflection','1');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('hardship-s2','hardship','Read the cited Quranic verses with their full surrounding context.','reflection','2');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('hardship-s3','hardship','Reflect on the Prophet’s ﷺ example of mercy during rejection.','reflection','3');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('hardship-s4','hardship','Make a sincere Dua and identify one realistic, lawful next action.','reflection','4');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('hardship-s5','hardship','Reach out for practical or professional support if the difficulty is overwhelming.','reflection','5');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('anxiety-s1','anxiety','Read and reflect on Quran 13:28 without expecting instant symptom relief.','reflection','1');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('anxiety-s2','anxiety','Learn the verified Dua from a reliable reciter or knowledgeable teacher.','reflection','2');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('anxiety-s3','anxiety','Contact someone trustworthy and identify practical sources of support.','reflection','3');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('anxiety-s4','anxiety','Seek healthcare advice if symptoms persist or interfere with daily life.','reflection','4');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('grief-s1','grief','Allow space for sadness and ordinary grieving.','reflection','1');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('grief-s2','grief','Read the account of the Prophet’s ﷺ grief without judging your emotions.','reflection','2');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('grief-s3','grief','Seek supportive company, care and Duas.','reflection','3');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('grief-s4','grief','Arrange additional care if grief seriously affects functioning or safety.','reflection','4');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('debt-s1','debt','Write down the amounts, due dates and people involved.','reflection','1');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('debt-s2','debt','Communicate honestly with the creditor and seek lawful accommodation.','reflection','2');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('debt-s3','debt','Review relevant Quranic and Hadith teachings in context.','reflection','3');
INSERT OR IGNORE INTO steps (id,journey_id,instruction,category,sort_order) VALUES ('debt-s4','debt','Seek reputable financial or legal guidance where appropriate.','reflection','4');
